const packs=[{"definition": {"id": "mud-cuttings-lab", "sceneId": "m1", "title": "岩屑岩性自动识别", "methods": ["cv"], "status": "ready", "version": "2.2.0", "updated": "2026-11-02", "tabs": {"background": {"label": "专业背景", "lede": "把岩屑的外观差异，变成可计算的特征距离。", "sections": [{"no": 1, "en": "CONCEPT", "title": "先读懂专业概念", "html": "<figure style=\"margin:18px 0;padding:18px;border:1px solid #d7e6de;border-radius:10px;background:#f5f9f6\"><div style=\"overflow-x:auto\" tabindex=\"0\" aria-label=\"专业示意图，窄屏可横向查看\"><svg viewBox=\"0 0 800 250\" role=\"img\" aria-label=\"把专业场景画出来\" style=\"display:block;width:100%;min-width:600px;font-family:system-ui,Microsoft YaHei,sans-serif\"><defs><marker id=\"arrow-把专业场景画出来\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3 0 6\" fill=\"none\" stroke=\"#4a967c\"/></marker></defs><text x=\"20\" y=\"27\" font-size=\"16\" font-weight=\"600\" fill=\"#2d715a\">把专业场景画出来</text><rect x=\"30\" y=\"76\" width=\"250\" height=\"42\" fill=\"#d4c29c\"/><rect x=\"30\" y=\"118\" width=\"250\" height=\"48\" fill=\"#93b2bb\"/><rect x=\"30\" y=\"166\" width=\"250\" height=\"42\" fill=\"#c2d3b1\"/><path d=\"M130 51v137h30V51\" stroke=\"#49696b\" stroke-width=\"8\" fill=\"none\"/><path d=\"M145 58v116m-6-10 6 10 6-10M169 175V63m-6 10 6-10 6 10\" stroke=\"#3c927d\" fill=\"none\" stroke-width=\"3\"/><text x=\"30\" y=\"48\" fill=\"#617f70\" font-size=\"12\">钻井液下行 / 携岩屑返出</text><path d=\"M183 65h145l32 55\" fill=\"none\" stroke=\"#4d947a\" stroke-width=\"2\"/><rect x=\"340\" y=\"120\" width=\"130\" height=\"77\" rx=\"12\" fill=\"#e2ecdf\" stroke=\"#85ad91\"/><circle cx=\"358\" cy=\"141\" r=\"4\" fill=\"#bc9f70\"/><circle cx=\"381\" cy=\"141\" r=\"5\" fill=\"#64899a\"/><circle cx=\"404\" cy=\"141\" r=\"6\" fill=\"#95ab80\"/><circle cx=\"427\" cy=\"141\" r=\"4\" fill=\"#bc9f70\"/><circle cx=\"450\" cy=\"141\" r=\"5\" fill=\"#64899a\"/><circle cx=\"358\" cy=\"162\" r=\"6\" fill=\"#95ab80\"/><circle cx=\"381\" cy=\"162\" r=\"4\" fill=\"#bc9f70\"/><circle cx=\"404\" cy=\"162\" r=\"5\" fill=\"#64899a\"/><circle cx=\"427\" cy=\"162\" r=\"6\" fill=\"#95ab80\"/><circle cx=\"450\" cy=\"162\" r=\"4\" fill=\"#bc9f70\"/><text x=\"365\" y=\"222\" font-size=\"13\" fill=\"#5e7e6c\">清洗、编号、取样</text><path d=\"M485 150h60m-7-6 7 6-7 6\" fill=\"none\" stroke=\"#4d947a\" stroke-width=\"2\"/><rect x=\"565\" y=\"70\" width=\"180\" height=\"130\" rx=\"12\" fill=\"#fff\" stroke=\"#a8c6b5\"/><text x=\"585\" y=\"98\" font-size=\"13\" fill=\"#4b7460\">图像中的三种线索</text><text x=\"585\" y=\"126\" font-size=\"14\" fill=\"#6d7e72\">颗粒 · 纹理 · 亮度</text><text x=\"585\" y=\"158\" font-size=\"12\" fill=\"#8b9c90\">k-NN：人工提取特征</text><text x=\"585\" y=\"182\" font-size=\"12\" fill=\"#3a8467\">CNN：从像素学习特征</text></svg></div><figcaption style=\"font-size:12px;color:#6a8275;margin-top:9px;line-height:1.8\">岩屑由钻井液带回地面，返出需要时间。样品编号必须对应迟到校正后的井深；混样与掉块会使“一个样本一个标签”失效。</figcaption></figure><div class=\"p-diagram\" style=\"padding:16px;background:#f4f8f6;border:1px solid #dce7e1;border-radius:10px\"><svg viewBox=\"0 0 685 125\" role=\"img\" aria-label=\"岩屑岩性自动识别概念流程\"><rect x=\"18\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e5f0e9\"/><text x=\"31\" y=\"51\" font-size=\"10\" fill=\"#81958d\">01</text><text x=\"90\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">岩屑样本</text><path d=\"M167 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"186\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e8eff5\"/><text x=\"199\" y=\"51\" font-size=\"10\" fill=\"#81958d\">02</text><text x=\"258\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">颗粒 / 亮度</text><path d=\"M335 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"354\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#eceaf5\"/><text x=\"367\" y=\"51\" font-size=\"10\" fill=\"#81958d\">03</text><text x=\"426\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">k-NN 近邻</text><path d=\"M503 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"522\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#f4edde\"/><text x=\"535\" y=\"51\" font-size=\"10\" fill=\"#81958d\">04</text><text x=\"594\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">岩性建议</text></svg></div><div><p><b>岩屑样本：</b>钻头切削岩石，循环钻井液把碎屑带回地面。样品必须对应迟到校正后的井深。</p><p><b>颗粒 / 亮度：</b>二维演示中，横轴代表颗粒特征，纵轴代表亮度特征。真实图像还需要纹理、形状与尺度信息。</p><p><b>k-NN 近邻：</b>用已标注样本的邻近关系进行分类，展示传统机器学习怎样形成决策边界。</p><p><b>岩性建议：</b>给出岩性建议和近邻票数，保留人工复核入口；混样可能同时包含多种岩性。</p></div>"}, {"no": 2, "en": "PROBLEM", "title": "业务问题与方法介入点", "html": "<p>人工描述需要同时观察颜色、颗粒与结构。样品混杂、光照差异和岩性相似性会影响一致性；仅凭一张图也无法可靠判断地层归属。</p><p><b>本例实现：</b>本示范实现 k 近邻分类：将特征归一化，计算欧氏距离，取距离最小的 k 个已标注训练点，以多数票确定类别。背景色逐网格重新分类，形成可视化决策边界。 学习实验实际训练 可训练 CNN：12×12 灰度图 → 4 个 3×3 卷积核 → ReLU → 2×2 平均池化 → 16 单元全连接 ReLU → 三类 Softmax；从合成岩屑纹理学习分类，所有卷积核与全连接层权重均参与反向传播。相同图像还提取亮度、离散度、横纵梯度供 k-NN 对照。 训练集 144、验证集 48、测试集 72；Adam、交叉熵、批量 12。按验证损失选轮数后再验收测试集，并与相同划分的 k-NN 比较。</p>"}, {"no": 3, "en": "DATA", "title": "实验数据与验证边界", "html": "<ul><li>72 个合成训练点：砂岩、泥岩、灰岩各 24 个</li><li>45 个独立合成测试点：各类 15 个，用于混淆矩阵</li><li>待识别点由颗粒、亮度滑块指定；全部特征无量纲</li><li>独立学习实验：144 个训练源样本、48 个验证源样本、72 个测试源样本；不同集合由独立种子生成，词表与输入缩放范围预先固定。</li></ul><p>所有数值为教学构造，可通过导出数据核查；现场应用需独立真实数据验证。</p>"}, {"no": 4, "en": "NEXT STEP", "title": "从示范走向真实智能化", "html": "<p>已实现浏览器端 可训练 CNN 训练与推理，卷积或全连接权重确实更新。图像是合成纹理，不是实际岩屑照片；需采集真实标注图像并按井、样品分组验证。 演示数据为教学合成，现场应用仍需独立真实资料、按井/样品分组验证与专业复核。</p><p>专业概念参考：<a href=\"https://www.slb.com/resource-library/oilfield-review/defining-series/defining-mud-logging\" target=\"_blank\" rel=\"noopener noreferrer\">SLB · Defining Mud Logging</a>。算法原理参考：<a href=\"https://www.tensorflow.org/tutorials/images/cnn\" target=\"_blank\" rel=\"noopener noreferrer\">TensorFlow CNN 教程</a>、<a href=\"https://scikit-learn.org/stable/modules/neural_networks_supervised.html\" target=\"_blank\" rel=\"noopener noreferrer\">MLP 与反向传播</a>、<a href=\"https://scikit-learn.org/stable/common_pitfalls.html\" target=\"_blank\" rel=\"noopener noreferrer\">防止数据泄漏</a>。本项目用原生 JavaScript 实现，并未加载这些库；合成数据与指标由本项目计算。</p>"}]}, "workflow": {"label": "案例流程", "title": "岩屑岩性自动识别的可复现实验流程", "lead": ["把岩屑的外观差异，变成可计算的特征距离。", "每一步都说明输入、处理方法、可观察结果与常见陷阱。"], "stats": [["关键步骤", "4"], ["执行位置", "浏览器"], ["数据类型", "教学样本"]], "steps": [{"name": "采样并校正井深", "role": "数据", "do": "给每份岩屑绑定采样深度、迟到时间与清洗记录。", "effect": "形成可追溯的样品编号。", "trap": "混样不能强行当成纯岩性标签。"}, {"name": "提取与归一化特征", "role": "特征", "do": "真实任务提取图像特征；此处生成颗粒和亮度两个教学特征。", "effect": "把图像问题转换为特征空间的点。", "trap": "不要把测试样本加入训练点。"}, {"name": "机器学习与深度学习对照", "role": "学习", "do": "保留原有专业基线；另用相同划分比较 k-NN 和 可训练 CNN。12×12 灰度图 → 4 个 3×3 卷积核 → ReLU → 2×2 平均池化 → 16 单元全连接 ReLU → 三类 Softmax。", "effect": "观察实际训练/验证损失、网络激活和参数变化。", "trap": "训练集更新权重，验证集选轮数；测试集不参与二者。"}, {"name": "冻结模型与独立验收", "role": "验收", "do": "恢复验证损失最低轮的权重，对 72 个测试样本推理；生成两种方法的混淆矩阵、准确率与宏平均 F1。", "effect": "浏览误判样本，导出数据、逐轮损失和模型权重。", "trap": "指标只对应合成任务；反复看测试集后再调参会削弱其独立验收意义。"}], "metrics": {"title": "看见训练过程，再判断结果", "html": "<figure style=\"margin:18px 0;padding:18px;border:1px solid #d7e6de;border-radius:10px;background:#f5f9f6\"><div style=\"overflow-x:auto\" tabindex=\"0\" aria-label=\"专业示意图，窄屏可横向查看\"><svg viewBox=\"0 0 800 250\" role=\"img\" aria-label=\"看清模型怎样学习\" style=\"display:block;width:100%;min-width:600px;font-family:system-ui,Microsoft YaHei,sans-serif\"><defs><marker id=\"arrow-看清模型怎样学习\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3 0 6\" fill=\"none\" stroke=\"#4a967c\"/></marker></defs><text x=\"20\" y=\"27\" font-size=\"16\" font-weight=\"600\" fill=\"#2d715a\">看清模型怎样学习</text><rect x=\"20\" y=\"62\" width=\"170\" height=\"64\" rx=\"8\" fill=\"#dfeee3\"/><text x=\"38\" y=\"88\" fill=\"#3b765a\" font-size=\"13\">训练 144 / 标签参与</text><text x=\"38\" y=\"110\" fill=\"#698c78\" font-size=\"11\">输入 → 前向计算 → 损失</text><path d=\"M202 94h54m-7-6 7 6-7 6\" fill=\"none\" stroke=\"#4d947a\" stroke-width=\"2\"/><rect x=\"265\" y=\"62\" width=\"255\" height=\"64\" rx=\"8\" fill=\"#e0e9f1\"/><text x=\"285\" y=\"87\" fill=\"#456d87\" font-size=\"13\">反向传播 · Adam 更新参数</text><text x=\"285\" y=\"109\" fill=\"#698393\" font-size=\"11\">每批 12 个样本 / 实时记录交叉熵</text><path d=\"M390 138v30H107v-30m-6 8 6-8 6 8\" fill=\"none\" stroke=\"#789c89\" stroke-width=\"2\"/><text x=\"145\" y=\"191\" fill=\"#6b8e77\" font-size=\"12\">重复训练，权重与损失真实变化</text><rect x=\"556\" y=\"62\" width=\"220\" height=\"64\" rx=\"8\" fill=\"#f1e9d8\"/><text x=\"574\" y=\"88\" fill=\"#99835c\" font-size=\"13\">验证 48 / 选择最低损失轮次</text><text x=\"574\" y=\"110\" fill=\"#99835c\" font-size=\"11\">不进入梯度，不更新权重</text><rect x=\"556\" y=\"160\" width=\"220\" height=\"64\" rx=\"8\" fill=\"#e1ece8\"/><text x=\"574\" y=\"186\" fill=\"#527a65\" font-size=\"13\">测试 72 / 冻结权重后验收</text><text x=\"574\" y=\"208\" fill=\"#789783\" font-size=\"11\">混淆矩阵 · 准确率 · 宏平均 F1</text><path d=\"M666 133v20m-6-8 6 8 6-8\" fill=\"none\" stroke=\"#789c89\" stroke-width=\"2\"/></svg></div><figcaption style=\"font-size:12px;color:#6a8275;margin-top:9px;line-height:1.8\"><b>可训练 CNN：</b>12×12 灰度图 → 4 个 3×3 卷积核 → ReLU → 2×2 平均池化 → 16 单元全连接 ReLU → 三类 Softmax。从合成岩屑纹理学习分类，所有卷积核与全连接层权重均参与反向传播。相同图像还提取亮度、离散度、横纵梯度供 k-NN 对照。</figcaption></figure><p>准确率 = 分类正确的测试点 / 45。混淆矩阵的行是真实标签、列是预测标签。改变噪声后训练点与测试点都从同一固定随机序列重新生成，标签不泄漏给推断函数。 神经网络实验与原专业基线使用不同教学数据，各自独立评估。新实验准确率为正确分类数/72，宏平均 F1 为各类 F1 的均值；只比较同一新实验中的 k-NN 和神经网络。</p><div class=\"p-diagram\" style=\"padding:16px;background:#f4f8f6;border:1px solid #dce7e1;border-radius:10px\"><svg viewBox=\"0 0 685 125\" role=\"img\" aria-label=\"岩屑岩性自动识别概念流程\"><rect x=\"18\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e5f0e9\"/><text x=\"31\" y=\"51\" font-size=\"10\" fill=\"#81958d\">01</text><text x=\"90\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">岩屑样本</text><path d=\"M167 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"186\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e8eff5\"/><text x=\"199\" y=\"51\" font-size=\"10\" fill=\"#81958d\">02</text><text x=\"258\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">颗粒 / 亮度</text><path d=\"M335 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"354\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#eceaf5\"/><text x=\"367\" y=\"51\" font-size=\"10\" fill=\"#81958d\">03</text><text x=\"426\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">k-NN 近邻</text><path d=\"M503 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"522\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#f4edde\"/><text x=\"535\" y=\"51\" font-size=\"10\" fill=\"#81958d\">04</text><text x=\"594\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">岩性建议</text></svg></div>"}, "fails": [{"name": "混样与掉块", "why": "单一标签无法解释混合岩屑，应引入组分估计。"}, {"name": "域偏移", "why": "灯光、镜头、洗样方式改变会移动特征分布。"}, {"name": "类间重叠", "why": "调高离散程度可观察分类边界和误差变化。"}]}, "demo": {"mode": "page", "html": "demo/index.html", "js": "demo/demo.js", "label": "交互演示", "intro": "把岩屑的外观差异，变成可计算的特征距离。", "height": 1100}}}, "path": "cases/mud-cuttings-lab/demo/index.html", "zip": "案例包/录井-岩屑岩性自动识别.zip"}, {"definition": {"id": "mud-gas-lab", "sceneId": "m2", "title": "气测异常智能解释", "methods": ["ts"], "status": "ready", "version": "2.2.0", "updated": "2026-11-02", "tabs": {"background": {"label": "专业背景", "lede": "先把气测信号放回正确的深度，再判断哪里值得关注。", "sections": [{"no": 1, "en": "CONCEPT", "title": "先读懂专业概念", "html": "<figure style=\"margin:18px 0;padding:18px;border:1px solid #d7e6de;border-radius:10px;background:#f5f9f6\"><div style=\"overflow-x:auto\" tabindex=\"0\" aria-label=\"专业示意图，窄屏可横向查看\"><svg viewBox=\"0 0 800 250\" role=\"img\" aria-label=\"把专业场景画出来\" style=\"display:block;width:100%;min-width:600px;font-family:system-ui,Microsoft YaHei,sans-serif\"><defs><marker id=\"arrow-把专业场景画出来\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3 0 6\" fill=\"none\" stroke=\"#4a967c\"/></marker></defs><text x=\"20\" y=\"27\" font-size=\"16\" font-weight=\"600\" fill=\"#2d715a\">把专业场景画出来</text><text x=\"30\" y=\"63\" font-size=\"13\" fill=\"#5d7f6d\">相同波形，为什么对应的地层会不同？</text><path d=\"M60 90h600M60 172h600\" stroke=\"#c5d7cd\"/><text x=\"665\" y=\"94\" font-size=\"12\" fill=\"#799284\">地层响应</text><text x=\"665\" y=\"176\" font-size=\"12\" fill=\"#799284\">地面观测</text><path d=\"M60 90h190l25-36h70l25 36h290\" stroke=\"#3b9579\" stroke-width=\"3\" fill=\"none\"/><path d=\"M60 172h290l25-36h70l25 36h190\" stroke=\"#b59767\" stroke-width=\"3\" fill=\"none\"/><path d=\"M278 46v155M378 46v155\" stroke=\"#9eb7a7\" stroke-dasharray=\"4 4\"/><path d=\"M368 210H288m8-6-8 6 8 6\" fill=\"none\" stroke=\"#478a70\" stroke-width=\"2\"/><text x=\"305\" y=\"236\" font-size=\"12\" fill=\"#478a70\">迟到校正：移回来源深度</text><rect x=\"500\" y=\"52\" width=\"145\" height=\"58\" rx=\"7\" fill=\"#e5efe6\"/><text x=\"512\" y=\"75\" font-size=\"12\" fill=\"#4b7e5f\">峰值不等于油气层</text><text x=\"512\" y=\"95\" font-size=\"11\" fill=\"#799284\">还需工况与岩屑复核</text></svg></div><figcaption style=\"font-size:12px;color:#6a8275;margin-top:9px;line-height:1.8\">示意图用水平位移表示迟到效应，不使用真实井场时间尺度。传统实验可调整校正量；神经网络实验使用已对齐的局部窗口，观察持续异常与短峰的区别。</figcaption></figure><div class=\"p-diagram\" style=\"padding:16px;background:#f4f8f6;border:1px solid #dce7e1;border-radius:10px\"><svg viewBox=\"0 0 685 125\" role=\"img\" aria-label=\"气测异常智能解释概念流程\"><rect x=\"18\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e5f0e9\"/><text x=\"31\" y=\"51\" font-size=\"10\" fill=\"#81958d\">01</text><text x=\"90\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">返出气体</text><path d=\"M167 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"186\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e8eff5\"/><text x=\"199\" y=\"51\" font-size=\"10\" fill=\"#81958d\">02</text><text x=\"258\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">迟到校正</text><path d=\"M335 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"354\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#eceaf5\"/><text x=\"367\" y=\"51\" font-size=\"10\" fill=\"#81958d\">03</text><text x=\"426\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">稳健异常检测</text><path d=\"M503 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"522\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#f4edde\"/><text x=\"535\" y=\"51\" font-size=\"10\" fill=\"#81958d\">04</text><text x=\"594\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">异常层段</text></svg></div><div><p><b>返出气体：</b>地面脱气装置获得返出钻井液中的气体信号，示范使用全烃 TG 曲线。</p><p><b>迟到校正：</b>钻进深度和地面观测不同步；此处人为延迟 8 个采样点以展示错位。</p><p><b>稳健异常检测：</b>以背景段中位数和 MAD 建立稳健基线，寻找持续偏高的信号。</p><p><b>异常层段：</b>把连续至少 3 点的异常合并成层段，再与岩屑、工况资料复核。</p></div>"}, {"no": 2, "en": "PROBLEM", "title": "业务问题与方法介入点", "html": "<p>地面观测存在迟到；短促的接单根气峰、噪声和背景漂移会干扰解释。单纯找峰值容易把工况影响误当成储层显示。</p><p><b>本例实现：</b>示范运行可解释的时序异常基线：用前 36 点中位数作为背景，以 1.4826 × MAD 估计稳健尺度（下限 0.07），超过背景 + 阈值 × 尺度的点标为候选，再排除少于 3 点的孤立片段。 学习实验实际训练 双隐藏层 MLP：11 点窗口 → 20 单元 ReLU → 12 单元 ReLU → 二类 Softmax；学习区分持续抬升与背景/短促工况峰；k-NN 使用相同的窗口输入。窗口含中心点后的观测，属于离线判别。 训练集 144、验证集 48、测试集 72；Adam、交叉熵、批量 12。按验证损失选轮数后再验收测试集，并与相同划分的 k-NN 比较。</p>"}, {"no": 3, "en": "DATA", "title": "实验数据与验证边界", "html": "<ul><li>160 点合成全烃曲线，1 点对应 1 m</li><li>真实异常区间为 2048–2070 m 和 2105–2130 m</li><li>另加入短促工况峰；原始观测固定迟到 8 点</li><li>独立学习实验：144 个训练源样本、48 个验证源样本、72 个测试源样本；不同集合由独立种子生成，词表与输入缩放范围预先固定。</li></ul><p>所有数值为教学构造，可通过导出数据核查；现场应用需独立真实数据验证。</p>"}, {"no": 4, "en": "NEXT STEP", "title": "从示范走向真实智能化", "html": "<p>已实现浏览器端 双隐藏层 MLP 训练与推理，卷积或全连接权重确实更新。这是持续异常窗口分类，不是实时预警，也不是油气水性质解释。 演示数据为教学合成，现场应用仍需独立真实资料、按井/样品分组验证与专业复核。</p><p>专业概念参考：<a href=\"https://www.slb.com/resource-library/oilfield-review/defining-series/defining-mud-logging\" target=\"_blank\" rel=\"noopener noreferrer\">SLB · Defining Mud Logging</a>。算法原理参考：<a href=\"https://www.tensorflow.org/tutorials/images/cnn\" target=\"_blank\" rel=\"noopener noreferrer\">TensorFlow CNN 教程</a>、<a href=\"https://scikit-learn.org/stable/modules/neural_networks_supervised.html\" target=\"_blank\" rel=\"noopener noreferrer\">MLP 与反向传播</a>、<a href=\"https://scikit-learn.org/stable/common_pitfalls.html\" target=\"_blank\" rel=\"noopener noreferrer\">防止数据泄漏</a>。本项目用原生 JavaScript 实现，并未加载这些库；合成数据与指标由本项目计算。</p>"}]}, "workflow": {"label": "案例流程", "title": "气测异常智能解释的可复现实验流程", "lead": ["先把气测信号放回正确的深度，再判断哪里值得关注。", "每一步都说明输入、处理方法、可观察结果与常见陷阱。"], "stats": [["关键步骤", "4"], ["执行位置", "浏览器"], ["数据类型", "教学样本"]], "steps": [{"name": "采集与质控", "role": "数据", "do": "统一全烃体积分数单位，记录采样间隔与工况事件。", "effect": "得到连续且单位一致的序列。", "trap": "仪器标定漂移会改变背景。"}, {"name": "迟到校正", "role": "特征", "do": "将地面观测向前移动指定采样点数。", "effect": "把气体信号与钻遇深度对齐。", "trap": "示范按固定点数；真实迟到随排量和井径变化。"}, {"name": "机器学习与深度学习对照", "role": "学习", "do": "保留原有专业基线；另用相同划分比较 k-NN 和 双隐藏层 MLP。11 点窗口 → 20 单元 ReLU → 12 单元 ReLU → 二类 Softmax。", "effect": "观察实际训练/验证损失、网络激活和参数变化。", "trap": "训练集更新权重，验证集选轮数；测试集不参与二者。"}, {"name": "冻结模型与独立验收", "role": "验收", "do": "恢复验证损失最低轮的权重，对 72 个测试样本推理；生成两种方法的混淆矩阵、准确率与宏平均 F1。", "effect": "浏览误判样本，导出数据、逐轮损失和模型权重。", "trap": "指标只对应合成任务；反复看测试集后再调参会削弱其独立验收意义。"}], "metrics": {"title": "看见训练过程，再判断结果", "html": "<figure style=\"margin:18px 0;padding:18px;border:1px solid #d7e6de;border-radius:10px;background:#f5f9f6\"><div style=\"overflow-x:auto\" tabindex=\"0\" aria-label=\"专业示意图，窄屏可横向查看\"><svg viewBox=\"0 0 800 250\" role=\"img\" aria-label=\"看清模型怎样学习\" style=\"display:block;width:100%;min-width:600px;font-family:system-ui,Microsoft YaHei,sans-serif\"><defs><marker id=\"arrow-看清模型怎样学习\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3 0 6\" fill=\"none\" stroke=\"#4a967c\"/></marker></defs><text x=\"20\" y=\"27\" font-size=\"16\" font-weight=\"600\" fill=\"#2d715a\">看清模型怎样学习</text><rect x=\"20\" y=\"62\" width=\"170\" height=\"64\" rx=\"8\" fill=\"#dfeee3\"/><text x=\"38\" y=\"88\" fill=\"#3b765a\" font-size=\"13\">训练 144 / 标签参与</text><text x=\"38\" y=\"110\" fill=\"#698c78\" font-size=\"11\">输入 → 前向计算 → 损失</text><path d=\"M202 94h54m-7-6 7 6-7 6\" fill=\"none\" stroke=\"#4d947a\" stroke-width=\"2\"/><rect x=\"265\" y=\"62\" width=\"255\" height=\"64\" rx=\"8\" fill=\"#e0e9f1\"/><text x=\"285\" y=\"87\" fill=\"#456d87\" font-size=\"13\">反向传播 · Adam 更新参数</text><text x=\"285\" y=\"109\" fill=\"#698393\" font-size=\"11\">每批 12 个样本 / 实时记录交叉熵</text><path d=\"M390 138v30H107v-30m-6 8 6-8 6 8\" fill=\"none\" stroke=\"#789c89\" stroke-width=\"2\"/><text x=\"145\" y=\"191\" fill=\"#6b8e77\" font-size=\"12\">重复训练，权重与损失真实变化</text><rect x=\"556\" y=\"62\" width=\"220\" height=\"64\" rx=\"8\" fill=\"#f1e9d8\"/><text x=\"574\" y=\"88\" fill=\"#99835c\" font-size=\"13\">验证 48 / 选择最低损失轮次</text><text x=\"574\" y=\"110\" fill=\"#99835c\" font-size=\"11\">不进入梯度，不更新权重</text><rect x=\"556\" y=\"160\" width=\"220\" height=\"64\" rx=\"8\" fill=\"#e1ece8\"/><text x=\"574\" y=\"186\" fill=\"#527a65\" font-size=\"13\">测试 72 / 冻结权重后验收</text><text x=\"574\" y=\"208\" fill=\"#789783\" font-size=\"11\">混淆矩阵 · 准确率 · 宏平均 F1</text><path d=\"M666 133v20m-6-8 6 8 6-8\" fill=\"none\" stroke=\"#789c89\" stroke-width=\"2\"/></svg></div><figcaption style=\"font-size:12px;color:#6a8275;margin-top:9px;line-height:1.8\"><b>双隐藏层 MLP：</b>11 点窗口 → 20 单元 ReLU → 12 单元 ReLU → 二类 Softmax。学习区分持续抬升与背景/短促工况峰；k-NN 使用相同的窗口输入。窗口含中心点后的观测，属于离线判别。</figcaption></figure><p>查准率 = TP / (TP + FP)，查全率 = TP / (TP + FN)，F1 = 2TP / (2TP + FP + FN)。以每个深度采样点为评价单位；空预测时相关指标记为 0。 神经网络实验与原专业基线使用不同教学数据，各自独立评估。新实验准确率为正确分类数/72，宏平均 F1 为各类 F1 的均值；只比较同一新实验中的 k-NN 和神经网络。</p><div class=\"p-diagram\" style=\"padding:16px;background:#f4f8f6;border:1px solid #dce7e1;border-radius:10px\"><svg viewBox=\"0 0 685 125\" role=\"img\" aria-label=\"气测异常智能解释概念流程\"><rect x=\"18\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e5f0e9\"/><text x=\"31\" y=\"51\" font-size=\"10\" fill=\"#81958d\">01</text><text x=\"90\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">返出气体</text><path d=\"M167 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"186\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e8eff5\"/><text x=\"199\" y=\"51\" font-size=\"10\" fill=\"#81958d\">02</text><text x=\"258\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">迟到校正</text><path d=\"M335 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"354\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#eceaf5\"/><text x=\"367\" y=\"51\" font-size=\"10\" fill=\"#81958d\">03</text><text x=\"426\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">稳健异常检测</text><path d=\"M503 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"522\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#f4edde\"/><text x=\"535\" y=\"51\" font-size=\"10\" fill=\"#81958d\">04</text><text x=\"594\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">异常层段</text></svg></div>"}, "fails": [{"name": "迟到校正错误", "why": "波形仍好看，层位却整体移动。"}, {"name": "背景段被污染", "why": "背景含显示或工况异常时，阈值会偏高。"}, {"name": "薄层被平滑", "why": "连续点约束可能牺牲短而真实的显示。"}]}, "demo": {"mode": "page", "html": "demo/index.html", "js": "demo/demo.js", "label": "交互演示", "intro": "先把气测信号放回正确的深度，再判断哪里值得关注。", "height": 1100}}}, "path": "cases/mud-gas-lab/demo/index.html", "zip": "案例包/录井-气测异常智能解释.zip"}, {"definition": {"id": "mud-fluorescence-lab", "sceneId": "m3", "title": "荧光图像智能判读", "methods": ["cv"], "status": "ready", "version": "2.2.0", "updated": "2026-11-02", "tabs": {"background": {"label": "专业背景", "lede": "观察的不只是亮不亮，还要知道亮度是怎样被测出来的。", "sections": [{"no": 1, "en": "CONCEPT", "title": "先读懂专业概念", "html": "<figure style=\"margin:18px 0;padding:18px;border:1px solid #d7e6de;border-radius:10px;background:#f5f9f6\"><div style=\"overflow-x:auto\" tabindex=\"0\" aria-label=\"专业示意图，窄屏可横向查看\"><svg viewBox=\"0 0 800 250\" role=\"img\" aria-label=\"把专业场景画出来\" style=\"display:block;width:100%;min-width:600px;font-family:system-ui,Microsoft YaHei,sans-serif\"><defs><marker id=\"arrow-把专业场景画出来\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3 0 6\" fill=\"none\" stroke=\"#4a967c\"/></marker></defs><text x=\"20\" y=\"27\" font-size=\"16\" font-weight=\"600\" fill=\"#2d715a\">把专业场景画出来</text><text x=\"35\" y=\"63\" font-size=\"12\" fill=\"#668675\">同一发光区域，拍摄曝光改变外观</text><rect x=\"35\" y=\"80\" width=\"205\" height=\"120\" rx=\"8\" fill=\"#182f3c\"/><circle cx=\"82\" cy=\"112\" r=\"8\" fill=\"#6c8d42\"/><circle cx=\"106\" cy=\"112\" r=\"11\" fill=\"#6c8d42\"/><circle cx=\"130\" cy=\"112\" r=\"14\" fill=\"#6c8d42\"/><circle cx=\"154\" cy=\"112\" r=\"8\" fill=\"#6c8d42\"/><circle cx=\"178\" cy=\"112\" r=\"11\" fill=\"#6c8d42\"/><circle cx=\"82\" cy=\"135\" r=\"14\" fill=\"#6c8d42\"/><circle cx=\"106\" cy=\"135\" r=\"8\" fill=\"#6c8d42\"/><circle cx=\"130\" cy=\"135\" r=\"11\" fill=\"#6c8d42\"/><circle cx=\"154\" cy=\"135\" r=\"14\" fill=\"#6c8d42\"/><circle cx=\"178\" cy=\"135\" r=\"8\" fill=\"#6c8d42\"/><circle cx=\"82\" cy=\"158\" r=\"11\" fill=\"#6c8d42\"/><circle cx=\"106\" cy=\"158\" r=\"14\" fill=\"#6c8d42\"/><circle cx=\"130\" cy=\"158\" r=\"8\" fill=\"#6c8d42\"/><circle cx=\"154\" cy=\"158\" r=\"11\" fill=\"#6c8d42\"/><circle cx=\"178\" cy=\"158\" r=\"14\" fill=\"#6c8d42\"/><text x=\"135\" y=\"225\" text-anchor=\"middle\" font-size=\"13\" fill=\"#5c8069\">低曝光</text><rect x=\"295\" y=\"80\" width=\"205\" height=\"120\" rx=\"8\" fill=\"#30414a\"/><circle cx=\"342\" cy=\"112\" r=\"8\" fill=\"#d9de8b\"/><circle cx=\"366\" cy=\"112\" r=\"11\" fill=\"#d9de8b\"/><circle cx=\"390\" cy=\"112\" r=\"14\" fill=\"#d9de8b\"/><circle cx=\"414\" cy=\"112\" r=\"8\" fill=\"#d9de8b\"/><circle cx=\"438\" cy=\"112\" r=\"11\" fill=\"#d9de8b\"/><circle cx=\"342\" cy=\"135\" r=\"14\" fill=\"#d9de8b\"/><circle cx=\"366\" cy=\"135\" r=\"8\" fill=\"#d9de8b\"/><circle cx=\"390\" cy=\"135\" r=\"11\" fill=\"#d9de8b\"/><circle cx=\"414\" cy=\"135\" r=\"14\" fill=\"#d9de8b\"/><circle cx=\"438\" cy=\"135\" r=\"8\" fill=\"#d9de8b\"/><circle cx=\"342\" cy=\"158\" r=\"11\" fill=\"#d9de8b\"/><circle cx=\"366\" cy=\"158\" r=\"14\" fill=\"#d9de8b\"/><circle cx=\"390\" cy=\"158\" r=\"8\" fill=\"#d9de8b\"/><circle cx=\"414\" cy=\"158\" r=\"11\" fill=\"#d9de8b\"/><circle cx=\"438\" cy=\"158\" r=\"14\" fill=\"#d9de8b\"/><text x=\"395\" y=\"225\" text-anchor=\"middle\" font-size=\"13\" fill=\"#5c8069\">高曝光</text><rect x=\"555\" y=\"80\" width=\"205\" height=\"120\" rx=\"8\" fill=\"#e0ece3\"/><circle cx=\"602\" cy=\"112\" r=\"8\" fill=\"#4a9b77\"/><circle cx=\"626\" cy=\"112\" r=\"11\" fill=\"#4a9b77\"/><circle cx=\"650\" cy=\"112\" r=\"14\" fill=\"#4a9b77\"/><circle cx=\"674\" cy=\"112\" r=\"8\" fill=\"#4a9b77\"/><circle cx=\"698\" cy=\"112\" r=\"11\" fill=\"#4a9b77\"/><circle cx=\"602\" cy=\"135\" r=\"14\" fill=\"#4a9b77\"/><circle cx=\"626\" cy=\"135\" r=\"8\" fill=\"#4a9b77\"/><circle cx=\"650\" cy=\"135\" r=\"11\" fill=\"#4a9b77\"/><circle cx=\"674\" cy=\"135\" r=\"14\" fill=\"#4a9b77\"/><circle cx=\"698\" cy=\"135\" r=\"8\" fill=\"#4a9b77\"/><circle cx=\"602\" cy=\"158\" r=\"11\" fill=\"#4a9b77\"/><circle cx=\"626\" cy=\"158\" r=\"14\" fill=\"#4a9b77\"/><circle cx=\"650\" cy=\"158\" r=\"8\" fill=\"#4a9b77\"/><circle cx=\"674\" cy=\"158\" r=\"11\" fill=\"#4a9b77\"/><circle cx=\"698\" cy=\"158\" r=\"14\" fill=\"#4a9b77\"/><text x=\"655\" y=\"225\" text-anchor=\"middle\" font-size=\"13\" fill=\"#5c8069\">校正后预测掩膜</text></svg></div><figcaption style=\"font-size:12px;color:#6a8275;margin-top:9px;line-height:1.8\">亮度同时受样品与拍摄条件影响。先做已知曝光校正，再用局部邻域预测中心像素；掩膜、真值和错误像素并排比较。过曝截断的信息不能靠除法恢复。</figcaption></figure><div class=\"p-diagram\" style=\"padding:16px;background:#f4f8f6;border:1px solid #dce7e1;border-radius:10px\"><svg viewBox=\"0 0 685 125\" role=\"img\" aria-label=\"荧光图像智能判读概念流程\"><rect x=\"18\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e5f0e9\"/><text x=\"31\" y=\"51\" font-size=\"10\" fill=\"#81958d\">01</text><text x=\"90\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">紫外照明</text><path d=\"M167 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"186\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e8eff5\"/><text x=\"199\" y=\"51\" font-size=\"10\" fill=\"#81958d\">02</text><text x=\"258\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">曝光标准化</text><path d=\"M335 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"354\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#eceaf5\"/><text x=\"367\" y=\"51\" font-size=\"10\" fill=\"#81958d\">03</text><text x=\"426\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">像素分割</text><path d=\"M503 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"522\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#f4edde\"/><text x=\"535\" y=\"51\" font-size=\"10\" fill=\"#81958d\">04</text><text x=\"594\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">特征分级</text></svg></div><div><p><b>紫外照明：</b>在受控紫外照明下观察样品的荧光响应，此处用合成像素演示。</p><p><b>曝光标准化：</b>参考曝光用于降低不同拍摄条件的影响；饱和像素不能被校正找回。</p><p><b>像素分割：</b>使用标准化强度阈值分出候选发光像素，计算区域面积。</p><p><b>特征分级：</b>合并面积与平均强度，比较四个教学原型获得分级建议。</p></div>"}, {"no": 2, "en": "PROBLEM", "title": "业务问题与方法介入点", "html": "<p>拍摄曝光变化会让同一份样品看起来更亮。若直接把亮度当作含油程度，成像条件就会混入解释结果；矿物荧光与污染也需要排查。</p><p><b>本例实现：</b>示范生成 60 × 60 像素图像，进行参考曝光校正，以 0.28 强度阈值提取发光区域。特征分数 = 0.6 × 发光面积占比 + 0.4 × 区域平均强度，并匹配 0.12、0.35、0.57、0.80 四个最近原型。 学习实验实际训练 局部窗口 MLP：曝光校正 3×3 邻域 → 20 单元 ReLU → 12 单元 ReLU → 中心像素二类 Softmax；从独立合成图像抽取像素邻域，学习发光/背景分类；与相同邻域的 k-NN 对照，并在额外留出图像上逐像素生成预测掩膜。 训练集 144、验证集 48、测试集 72；Adam、交叉熵、批量 12。按验证损失选轮数后再验收测试集，并与相同划分的 k-NN 比较。</p>"}, {"no": 3, "en": "DATA", "title": "实验数据与验证边界", "html": "<ul><li>3,600 个合成像素，每个像素保留发光真值标签</li><li>可调真实覆盖率、强度及相机曝光倍率</li><li>参考曝光倍率已知，用于对比校正前后的分类变化</li><li>独立学习实验：144 个训练源样本、48 个验证源样本、72 个测试源样本；不同集合由独立种子生成，词表与输入缩放范围预先固定。</li></ul><p>所有数值为教学构造，可通过导出数据核查；现场应用需独立真实数据验证。</p>"}, {"no": 4, "en": "NEXT STEP", "title": "从示范走向真实智能化", "html": "<p>已实现浏览器端 局部窗口 MLP 训练与推理，卷积或全连接权重确实更新。展平邻域输入的是 MLP，不是 CNN；像素标签不能直接换算含油量。 演示数据为教学合成，现场应用仍需独立真实资料、按井/样品分组验证与专业复核。</p><p>专业概念参考：<a href=\"https://www.slb.com/resource-library/oilfield-review/defining-series/defining-mud-logging\" target=\"_blank\" rel=\"noopener noreferrer\">SLB · Defining Mud Logging</a>。算法原理参考：<a href=\"https://www.tensorflow.org/tutorials/images/cnn\" target=\"_blank\" rel=\"noopener noreferrer\">TensorFlow CNN 教程</a>、<a href=\"https://scikit-learn.org/stable/modules/neural_networks_supervised.html\" target=\"_blank\" rel=\"noopener noreferrer\">MLP 与反向传播</a>、<a href=\"https://scikit-learn.org/stable/common_pitfalls.html\" target=\"_blank\" rel=\"noopener noreferrer\">防止数据泄漏</a>。本项目用原生 JavaScript 实现，并未加载这些库；合成数据与指标由本项目计算。</p>"}]}, "workflow": {"label": "案例流程", "title": "荧光图像智能判读的可复现实验流程", "lead": ["观察的不只是亮不亮，还要知道亮度是怎样被测出来的。", "每一步都说明输入、处理方法、可观察结果与常见陷阱。"], "stats": [["关键步骤", "4"], ["执行位置", "浏览器"], ["数据类型", "教学样本"]], "steps": [{"name": "规范成像条件", "role": "数据", "do": "固定紫外灯、拍摄距离、曝光参数与样品处理流程。", "effect": "让不同照片可以比较。", "trap": "灯源变化可能比样品差异更明显。"}, {"name": "参考曝光校正", "role": "特征", "do": "把观测强度除以参考曝光倍率。", "effect": "减小曝光变化造成的系统偏移。", "trap": "过曝截断后的信息无法恢复。"}, {"name": "机器学习与深度学习对照", "role": "学习", "do": "保留原有专业基线；另用相同划分比较 k-NN 和 局部窗口 MLP。曝光校正 3×3 邻域 → 20 单元 ReLU → 12 单元 ReLU → 中心像素二类 Softmax。", "effect": "观察实际训练/验证损失、网络激活和参数变化。", "trap": "训练集更新权重，验证集选轮数；测试集不参与二者。"}, {"name": "冻结模型与独立验收", "role": "验收", "do": "恢复验证损失最低轮的权重，对 72 个测试样本推理；生成两种方法的混淆矩阵、准确率与宏平均 F1。", "effect": "浏览误判样本，导出数据、逐轮损失和模型权重。", "trap": "指标只对应合成任务；反复看测试集后再调参会削弱其独立验收意义。"}], "metrics": {"title": "看见训练过程，再判断结果", "html": "<figure style=\"margin:18px 0;padding:18px;border:1px solid #d7e6de;border-radius:10px;background:#f5f9f6\"><div style=\"overflow-x:auto\" tabindex=\"0\" aria-label=\"专业示意图，窄屏可横向查看\"><svg viewBox=\"0 0 800 250\" role=\"img\" aria-label=\"看清模型怎样学习\" style=\"display:block;width:100%;min-width:600px;font-family:system-ui,Microsoft YaHei,sans-serif\"><defs><marker id=\"arrow-看清模型怎样学习\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3 0 6\" fill=\"none\" stroke=\"#4a967c\"/></marker></defs><text x=\"20\" y=\"27\" font-size=\"16\" font-weight=\"600\" fill=\"#2d715a\">看清模型怎样学习</text><rect x=\"20\" y=\"62\" width=\"170\" height=\"64\" rx=\"8\" fill=\"#dfeee3\"/><text x=\"38\" y=\"88\" fill=\"#3b765a\" font-size=\"13\">训练 144 / 标签参与</text><text x=\"38\" y=\"110\" fill=\"#698c78\" font-size=\"11\">输入 → 前向计算 → 损失</text><path d=\"M202 94h54m-7-6 7 6-7 6\" fill=\"none\" stroke=\"#4d947a\" stroke-width=\"2\"/><rect x=\"265\" y=\"62\" width=\"255\" height=\"64\" rx=\"8\" fill=\"#e0e9f1\"/><text x=\"285\" y=\"87\" fill=\"#456d87\" font-size=\"13\">反向传播 · Adam 更新参数</text><text x=\"285\" y=\"109\" fill=\"#698393\" font-size=\"11\">每批 12 个样本 / 实时记录交叉熵</text><path d=\"M390 138v30H107v-30m-6 8 6-8 6 8\" fill=\"none\" stroke=\"#789c89\" stroke-width=\"2\"/><text x=\"145\" y=\"191\" fill=\"#6b8e77\" font-size=\"12\">重复训练，权重与损失真实变化</text><rect x=\"556\" y=\"62\" width=\"220\" height=\"64\" rx=\"8\" fill=\"#f1e9d8\"/><text x=\"574\" y=\"88\" fill=\"#99835c\" font-size=\"13\">验证 48 / 选择最低损失轮次</text><text x=\"574\" y=\"110\" fill=\"#99835c\" font-size=\"11\">不进入梯度，不更新权重</text><rect x=\"556\" y=\"160\" width=\"220\" height=\"64\" rx=\"8\" fill=\"#e1ece8\"/><text x=\"574\" y=\"186\" fill=\"#527a65\" font-size=\"13\">测试 72 / 冻结权重后验收</text><text x=\"574\" y=\"208\" fill=\"#789783\" font-size=\"11\">混淆矩阵 · 准确率 · 宏平均 F1</text><path d=\"M666 133v20m-6-8 6 8 6-8\" fill=\"none\" stroke=\"#789c89\" stroke-width=\"2\"/></svg></div><figcaption style=\"font-size:12px;color:#6a8275;margin-top:9px;line-height:1.8\"><b>局部窗口 MLP：</b>曝光校正 3×3 邻域 → 20 单元 ReLU → 12 单元 ReLU → 中心像素二类 Softmax。从独立合成图像抽取像素邻域，学习发光/背景分类；与相同邻域的 k-NN 对照，并在额外留出图像上逐像素生成预测掩膜。</figcaption></figure><p>像素 F1 衡量分割掩码和合成真值的重合。覆盖率是预测发光像素 / 3,600；平均强度仅对被检出的像素计算。分级不用于现场决策。 神经网络实验与原专业基线使用不同教学数据，各自独立评估。新实验准确率为正确分类数/72，宏平均 F1 为各类 F1 的均值；只比较同一新实验中的 k-NN 和神经网络。</p><div class=\"p-diagram\" style=\"padding:16px;background:#f4f8f6;border:1px solid #dce7e1;border-radius:10px\"><svg viewBox=\"0 0 685 125\" role=\"img\" aria-label=\"荧光图像智能判读概念流程\"><rect x=\"18\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e5f0e9\"/><text x=\"31\" y=\"51\" font-size=\"10\" fill=\"#81958d\">01</text><text x=\"90\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">紫外照明</text><path d=\"M167 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"186\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e8eff5\"/><text x=\"199\" y=\"51\" font-size=\"10\" fill=\"#81958d\">02</text><text x=\"258\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">曝光标准化</text><path d=\"M335 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"354\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#eceaf5\"/><text x=\"367\" y=\"51\" font-size=\"10\" fill=\"#81958d\">03</text><text x=\"426\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">像素分割</text><path d=\"M503 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"522\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#f4edde\"/><text x=\"535\" y=\"51\" font-size=\"10\" fill=\"#81958d\">04</text><text x=\"594\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">特征分级</text></svg></div>"}, "fails": [{"name": "曝光饱和", "why": "强信号截断后，标准化也不能完整恢复。"}, {"name": "矿物与污染荧光", "why": "有发光不代表存在可采油气。"}, {"name": "跨设备迁移", "why": "更换相机或紫外灯需要重新校准。"}]}, "demo": {"mode": "page", "html": "demo/index.html", "js": "demo/demo.js", "label": "交互演示", "intro": "观察的不只是亮不亮，还要知道亮度是怎样被测出来的。", "height": 1100}}}, "path": "cases/mud-fluorescence-lab/demo/index.html", "zip": "案例包/录井-荧光图像智能判读.zip"}, {"definition": {"id": "mud-layering-lab", "sceneId": "m4", "title": "钻时曲线地层划分", "methods": ["ts"], "status": "ready", "version": "2.2.0", "updated": "2026-11-02", "tabs": {"background": {"label": "专业背景", "lede": "曲线的转折，可能来自地层，也可能来自钻井工况。", "sections": [{"no": 1, "en": "CONCEPT", "title": "先读懂专业概念", "html": "<figure style=\"margin:18px 0;padding:18px;border:1px solid #d7e6de;border-radius:10px;background:#f5f9f6\"><div style=\"overflow-x:auto\" tabindex=\"0\" aria-label=\"专业示意图，窄屏可横向查看\"><svg viewBox=\"0 0 800 250\" role=\"img\" aria-label=\"把专业场景画出来\" style=\"display:block;width:100%;min-width:600px;font-family:system-ui,Microsoft YaHei,sans-serif\"><defs><marker id=\"arrow-把专业场景画出来\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3 0 6\" fill=\"none\" stroke=\"#4a967c\"/></marker></defs><text x=\"20\" y=\"27\" font-size=\"16\" font-weight=\"600\" fill=\"#2d715a\">把专业场景画出来</text><text x=\"32\" y=\"63\" font-size=\"13\" fill=\"#63856e\">地层变化</text><text x=\"280\" y=\"63\" font-size=\"13\" fill=\"#63856e\">钻时响应</text><text x=\"548\" y=\"63\" font-size=\"13\" fill=\"#63856e\">工况也会改变曲线</text><rect x=\"30\" y=\"80\" width=\"150\" height=\"40\" fill=\"#ccb58b\"/><rect x=\"30\" y=\"120\" width=\"150\" height=\"50\" fill=\"#9bb9bf\"/><rect x=\"30\" y=\"170\" width=\"150\" height=\"40\" fill=\"#c0cfad\"/><path d=\"M180 120h280M180 170h280\" stroke=\"#b4cbb9\" stroke-dasharray=\"5 4\"/><path d=\"M300 80v36h80v54h-60v40\" fill=\"none\" stroke=\"#3d9276\" stroke-width=\"3\"/><path d=\"M580 80v55h-32v35h32v40\" fill=\"none\" stroke=\"#c19a65\" stroke-width=\"3\"/><text x=\"610\" y=\"128\" font-size=\"12\" fill=\"#957950\">钻压增大</text><text x=\"610\" y=\"150\" font-size=\"12\" fill=\"#957950\">钻时缩短</text><text x=\"610\" y=\"192\" font-size=\"11\" fill=\"#789080\">可能产生伪界面</text><text x=\"31\" y=\"236\" font-size=\"12\" fill=\"#5d806b\">井深向下增加；钻时为钻进单位长度所需时间，单位 min/m。</text></svg></div><figcaption style=\"font-size:12px;color:#6a8275;margin-top:9px;line-height:1.8\">图中曲线为概念示意。工况补偿与层界识别分开讲解；MLP 对 11 点窗口给出界面候选分数，动态规划基线展示完整分层，两者评价对象不同。</figcaption></figure><div class=\"p-diagram\" style=\"padding:16px;background:#f4f8f6;border:1px solid #dce7e1;border-radius:10px\"><svg viewBox=\"0 0 685 125\" role=\"img\" aria-label=\"钻时曲线地层划分概念流程\"><rect x=\"18\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e5f0e9\"/><text x=\"31\" y=\"51\" font-size=\"10\" fill=\"#81958d\">01</text><text x=\"90\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">钻时序列</text><path d=\"M167 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"186\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e8eff5\"/><text x=\"199\" y=\"51\" font-size=\"10\" fill=\"#81958d\">02</text><text x=\"258\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">工况校正</text><path d=\"M335 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"354\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#eceaf5\"/><text x=\"367\" y=\"51\" font-size=\"10\" fill=\"#81958d\">03</text><text x=\"426\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">变点分段</text><path d=\"M503 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"522\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#f4edde\"/><text x=\"535\" y=\"51\" font-size=\"10\" fill=\"#81958d\">04</text><text x=\"594\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">层界复核</text></svg></div><div><p><b>钻时序列：</b>钻时表示钻进单位长度所需时间，单位 min/m；与机械钻速 m/h 互为换算关系。</p><p><b>工况校正：</b>模拟钻压变化会改变钻时，先校正以减少工况引入的伪界面。</p><p><b>变点分段：</b>用分段常数拟合解释序列，兼顾拟合误差与界面数量。</p><p><b>层界复核：</b>将预测界面与岩屑和气测共同验证，不能只凭钻时命名岩性。</p></div>"}, {"no": 2, "en": "PROBLEM", "title": "业务问题与方法介入点", "html": "<p>同样的岩性在不同钻压和转速下可能有不同钻时。噪声会制造短段，过度平滑又可能漏掉地层界面。</p><p><b>本例实现：</b>本示范使用动态规划最小化“各段平方误差之和 + λ × 界面数”。最小段长 8 m；用累积和快速计算区间误差。改变 λ 可以直接观察过分段与欠分段。 学习实验实际训练 窗口 MLP：工况补偿 11 点窗口 → 20 单元 ReLU → 12 单元 ReLU → 界面候选二类 Softmax；学习局部钻时窗口是否位于界面附近，与相同窗口的 k-NN 对照。动态规划完整分段仍在“原有专业基线实验”中保留。 训练集 144、验证集 48、测试集 72；Adam、交叉熵、批量 12。按验证损失选轮数后再验收测试集，并与相同划分的 k-NN 比较。</p>"}, {"no": 3, "en": "DATA", "title": "实验数据与验证边界", "html": "<ul><li>2000–2159 m 的 160 个合成钻时采样点</li><li>真实界面为 2040、2080、2120 m</li><li>2065–2099 m 人为设置 1.55 倍钻压因子，原始钻时按该因子缩短</li><li>独立学习实验：144 个训练源样本、48 个验证源样本、72 个测试源样本；不同集合由独立种子生成，词表与输入缩放范围预先固定。</li></ul><p>所有数值为教学构造，可通过导出数据核查；现场应用需独立真实数据验证。</p>"}, {"no": 4, "en": "NEXT STEP", "title": "从示范走向真实智能化", "html": "<p>已实现浏览器端 窗口 MLP 训练与推理，卷积或全连接权重确实更新。窗口分类不等于完整地层解释，不给地层命名；补偿关系仅为合成设定。 演示数据为教学合成，现场应用仍需独立真实资料、按井/样品分组验证与专业复核。</p><p>专业概念参考：<a href=\"https://www.slb.com/resource-library/oilfield-review/defining-series/defining-mud-logging\" target=\"_blank\" rel=\"noopener noreferrer\">SLB · Defining Mud Logging</a>。算法原理参考：<a href=\"https://www.tensorflow.org/tutorials/images/cnn\" target=\"_blank\" rel=\"noopener noreferrer\">TensorFlow CNN 教程</a>、<a href=\"https://scikit-learn.org/stable/modules/neural_networks_supervised.html\" target=\"_blank\" rel=\"noopener noreferrer\">MLP 与反向传播</a>、<a href=\"https://scikit-learn.org/stable/common_pitfalls.html\" target=\"_blank\" rel=\"noopener noreferrer\">防止数据泄漏</a>。本项目用原生 JavaScript 实现，并未加载这些库；合成数据与指标由本项目计算。</p>"}]}, "workflow": {"label": "案例流程", "title": "钻时曲线地层划分的可复现实验流程", "lead": ["曲线的转折，可能来自地层，也可能来自钻井工况。", "每一步都说明输入、处理方法、可观察结果与常见陷阱。"], "stats": [["关键步骤", "4"], ["执行位置", "浏览器"], ["数据类型", "教学样本"]], "steps": [{"name": "整理深度序列", "role": "数据", "do": "将钻时统一为 min/m，检查缺测与重复深度。", "effect": "生成有序且尺度一致的输入。", "trap": "不要混用钻速和钻时的单位。"}, {"name": "工况归一化", "role": "特征", "do": "按合成钻压因子补偿原始钻时。", "effect": "消除预设的工况响应。", "trap": "真实项目应独立标定校正模型。"}, {"name": "机器学习与深度学习对照", "role": "学习", "do": "保留原有专业基线；另用相同划分比较 k-NN 和 窗口 MLP。工况补偿 11 点窗口 → 20 单元 ReLU → 12 单元 ReLU → 界面候选二类 Softmax。", "effect": "观察实际训练/验证损失、网络激活和参数变化。", "trap": "训练集更新权重，验证集选轮数；测试集不参与二者。"}, {"name": "冻结模型与独立验收", "role": "验收", "do": "恢复验证损失最低轮的权重，对 72 个测试样本推理；生成两种方法的混淆矩阵、准确率与宏平均 F1。", "effect": "浏览误判样本，导出数据、逐轮损失和模型权重。", "trap": "指标只对应合成任务；反复看测试集后再调参会削弱其独立验收意义。"}], "metrics": {"title": "看见训练过程，再判断结果", "html": "<figure style=\"margin:18px 0;padding:18px;border:1px solid #d7e6de;border-radius:10px;background:#f5f9f6\"><div style=\"overflow-x:auto\" tabindex=\"0\" aria-label=\"专业示意图，窄屏可横向查看\"><svg viewBox=\"0 0 800 250\" role=\"img\" aria-label=\"看清模型怎样学习\" style=\"display:block;width:100%;min-width:600px;font-family:system-ui,Microsoft YaHei,sans-serif\"><defs><marker id=\"arrow-看清模型怎样学习\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3 0 6\" fill=\"none\" stroke=\"#4a967c\"/></marker></defs><text x=\"20\" y=\"27\" font-size=\"16\" font-weight=\"600\" fill=\"#2d715a\">看清模型怎样学习</text><rect x=\"20\" y=\"62\" width=\"170\" height=\"64\" rx=\"8\" fill=\"#dfeee3\"/><text x=\"38\" y=\"88\" fill=\"#3b765a\" font-size=\"13\">训练 144 / 标签参与</text><text x=\"38\" y=\"110\" fill=\"#698c78\" font-size=\"11\">输入 → 前向计算 → 损失</text><path d=\"M202 94h54m-7-6 7 6-7 6\" fill=\"none\" stroke=\"#4d947a\" stroke-width=\"2\"/><rect x=\"265\" y=\"62\" width=\"255\" height=\"64\" rx=\"8\" fill=\"#e0e9f1\"/><text x=\"285\" y=\"87\" fill=\"#456d87\" font-size=\"13\">反向传播 · Adam 更新参数</text><text x=\"285\" y=\"109\" fill=\"#698393\" font-size=\"11\">每批 12 个样本 / 实时记录交叉熵</text><path d=\"M390 138v30H107v-30m-6 8 6-8 6 8\" fill=\"none\" stroke=\"#789c89\" stroke-width=\"2\"/><text x=\"145\" y=\"191\" fill=\"#6b8e77\" font-size=\"12\">重复训练，权重与损失真实变化</text><rect x=\"556\" y=\"62\" width=\"220\" height=\"64\" rx=\"8\" fill=\"#f1e9d8\"/><text x=\"574\" y=\"88\" fill=\"#99835c\" font-size=\"13\">验证 48 / 选择最低损失轮次</text><text x=\"574\" y=\"110\" fill=\"#99835c\" font-size=\"11\">不进入梯度，不更新权重</text><rect x=\"556\" y=\"160\" width=\"220\" height=\"64\" rx=\"8\" fill=\"#e1ece8\"/><text x=\"574\" y=\"186\" fill=\"#527a65\" font-size=\"13\">测试 72 / 冻结权重后验收</text><text x=\"574\" y=\"208\" fill=\"#789783\" font-size=\"11\">混淆矩阵 · 准确率 · 宏平均 F1</text><path d=\"M666 133v20m-6-8 6 8 6-8\" fill=\"none\" stroke=\"#789c89\" stroke-width=\"2\"/></svg></div><figcaption style=\"font-size:12px;color:#6a8275;margin-top:9px;line-height:1.8\"><b>窗口 MLP：</b>工况补偿 11 点窗口 → 20 单元 ReLU → 12 单元 ReLU → 界面候选二类 Softmax。学习局部钻时窗口是否位于界面附近，与相同窗口的 k-NN 对照。动态规划完整分段仍在“原有专业基线实验”中保留。</figcaption></figure><p>真实界面和预测界面一对一匹配，容差 ±3 m。F1 = 2 × 命中界面 / (预测界面数 + 真实界面数)。MAE 只统计已匹配界面；无命中时显示“—”。 神经网络实验与原专业基线使用不同教学数据，各自独立评估。新实验准确率为正确分类数/72，宏平均 F1 为各类 F1 的均值；只比较同一新实验中的 k-NN 和神经网络。</p><div class=\"p-diagram\" style=\"padding:16px;background:#f4f8f6;border:1px solid #dce7e1;border-radius:10px\"><svg viewBox=\"0 0 685 125\" role=\"img\" aria-label=\"钻时曲线地层划分概念流程\"><rect x=\"18\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e5f0e9\"/><text x=\"31\" y=\"51\" font-size=\"10\" fill=\"#81958d\">01</text><text x=\"90\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">钻时序列</text><path d=\"M167 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"186\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e8eff5\"/><text x=\"199\" y=\"51\" font-size=\"10\" fill=\"#81958d\">02</text><text x=\"258\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">工况校正</text><path d=\"M335 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"354\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#eceaf5\"/><text x=\"367\" y=\"51\" font-size=\"10\" fill=\"#81958d\">03</text><text x=\"426\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">变点分段</text><path d=\"M503 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"522\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#f4edde\"/><text x=\"535\" y=\"51\" font-size=\"10\" fill=\"#81958d\">04</text><text x=\"594\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">层界复核</text></svg></div>"}, "fails": [{"name": "工况造成伪界面", "why": "关闭校正后可看到非地质因素的影响。"}, {"name": "噪声诱发过分段", "why": "适当增加惩罚项可提高稳定性。"}, {"name": "薄层分辨率受限", "why": "最小段长约束会让薄于 8 m 的层段难以出现。"}]}, "demo": {"mode": "page", "html": "demo/index.html", "js": "demo/demo.js", "label": "交互演示", "intro": "曲线的转折，可能来自地层，也可能来自钻井工况。", "height": 1100}}}, "path": "cases/mud-layering-lab/demo/index.html", "zip": "案例包/录井-钻时曲线地层划分.zip"}, {"definition": {"id": "mud-report-lab", "sceneId": "m5", "title": "录井报告自动生成", "methods": ["nlp"], "status": "ready", "version": "2.2.0", "updated": "2026-11-02", "tabs": {"background": {"label": "专业背景", "lede": "让报告中的每一个结论，都能回到原始记录。", "sections": [{"no": 1, "en": "CONCEPT", "title": "先读懂专业概念", "html": "<figure style=\"margin:18px 0;padding:18px;border:1px solid #d7e6de;border-radius:10px;background:#f5f9f6\"><div style=\"overflow-x:auto\" tabindex=\"0\" aria-label=\"专业示意图，窄屏可横向查看\"><svg viewBox=\"0 0 800 250\" role=\"img\" aria-label=\"把专业场景画出来\" style=\"display:block;width:100%;min-width:600px;font-family:system-ui,Microsoft YaHei,sans-serif\"><defs><marker id=\"arrow-把专业场景画出来\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3 0 6\" fill=\"none\" stroke=\"#4a967c\"/></marker></defs><text x=\"20\" y=\"27\" font-size=\"16\" font-weight=\"600\" fill=\"#2d715a\">把专业场景画出来</text><rect x=\"30\" y=\"75\" width=\"220\" height=\"130\" rx=\"8\" fill=\"#fff\" stroke=\"#b7cfc0\"/><text x=\"47\" y=\"101\" font-size=\"13\" fill=\"#62816d\">现场记录</text><rect x=\"43\" y=\"113\" width=\"192\" height=\"28\" rx=\"4\" fill=\"#e0efe3\"/><text x=\"50\" y=\"132\" font-size=\"12\" fill=\"#428364\">全烃连续异常 / 砂岩 / 荧光</text><text x=\"49\" y=\"162\" font-size=\"12\" fill=\"#7e9485\">井段：原文提取</text><text x=\"49\" y=\"188\" font-size=\"12\" fill=\"#ab925f\">缺失字段：待补充</text><path d=\"M263 140h55m-7-6 7 6-7 6\" fill=\"none\" stroke=\"#4d947a\" stroke-width=\"2\"/><rect x=\"330\" y=\"90\" width=\"160\" height=\"100\" rx=\"8\" fill=\"#e7efe4\"/><text x=\"350\" y=\"119\" font-size=\"12\" fill=\"#53755e\">固定词表 → 词向量</text><text x=\"350\" y=\"145\" font-size=\"13\" fill=\"#32805f\">MLP 意图分类</text><text x=\"350\" y=\"171\" font-size=\"11\" fill=\"#81947f\">学习选择复核方向</text><path d=\"M502 140h45m-7-6 7 6-7 6\" fill=\"none\" stroke=\"#4d947a\" stroke-width=\"2\"/><rect x=\"560\" y=\"75\" width=\"205\" height=\"130\" rx=\"8\" fill=\"#fff\" stroke=\"#b7cfc0\"/><text x=\"580\" y=\"103\" font-size=\"13\" fill=\"#4d7b60\">受控报告初稿</text><text x=\"580\" y=\"133\" font-size=\"12\" fill=\"#698373\">事实：保留原文依据</text><text x=\"580\" y=\"158\" font-size=\"12\" fill=\"#698373\">建议：显示复核</text><text x=\"580\" y=\"184\" font-size=\"12\" fill=\"#ab925f\">人工审核后使用</text></svg></div><figcaption style=\"font-size:12px;color:#6a8275;margin-top:9px;line-height:1.8\">神经网络只负责三种教学意图的分类；实体抽取、检索和模板报告保留可追溯的原文。意图分数不能证明地质事实，缺失值不由模型猜测补齐。</figcaption></figure><div class=\"p-diagram\" style=\"padding:16px;background:#f4f8f6;border:1px solid #dce7e1;border-radius:10px\"><svg viewBox=\"0 0 685 125\" role=\"img\" aria-label=\"录井报告自动生成概念流程\"><rect x=\"18\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e5f0e9\"/><text x=\"31\" y=\"51\" font-size=\"10\" fill=\"#81958d\">01</text><text x=\"90\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">现场记录</text><path d=\"M167 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"186\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e8eff5\"/><text x=\"199\" y=\"51\" font-size=\"10\" fill=\"#81958d\">02</text><text x=\"258\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">实体抽取</text><path d=\"M335 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"354\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#eceaf5\"/><text x=\"367\" y=\"51\" font-size=\"10\" fill=\"#81958d\">03</text><text x=\"426\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">参考检索</text><path d=\"M503 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"522\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#f4edde\"/><text x=\"535\" y=\"51\" font-size=\"10\" fill=\"#81958d\">04</text><text x=\"594\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">报告初稿</text></svg></div><div><p><b>现场记录：</b>输入井号、深度、岩性、全烃与荧光记录，保留原文供追溯。</p><p><b>实体抽取：</b>用词典和正则规则抽取实体；未识别的信息明确显示为待补充。</p><p><b>参考检索：</b>对三条教学参考建议计算 TF-IDF 余弦相似度，展示排序。</p><p><b>报告初稿：</b>用固定模板组织已抽取信息，进行范围与完整性检查。</p></div>"}, {"no": 2, "en": "PROBLEM", "title": "业务问题与方法介入点", "html": "<p>从多份现场记录整理报告时，容易遗漏字段或混淆单位。自动生成若补造缺失值，表面流畅却会破坏报告可追溯性。</p><p><b>本例实现：</b>示范实现轻量 NLP 链路：正则抽取五类字段；行业词典计数建立 TF-IDF 向量；余弦相似度检索建议；模板生成报告并逐项检查。原文高亮展示每个字段来自哪里。 学习实验实际训练 文本 MLP：固定 24 词表二值向量 → 20 单元 ReLU → 12 单元 ReLU → 三种复核意图；学习显示复核、工况排查和层界复核三种意图，与词向量 k-NN 对照。报告实体抽取和模板初稿仍保留原文依据。 训练集 144、验证集 48、测试集 72；Adam、交叉熵、批量 12。按验证损失选轮数后再验收测试集，并与相同划分的 k-NN 比较。</p>"}, {"no": 3, "en": "DATA", "title": "实验数据与验证边界", "html": "<ul><li>可编辑的教学现场记录，不含真实井资料</li><li>5 个目标实体：井号、井段、岩性、全烃、荧光</li><li>3 条内置参考建议；TF-IDF 词表与得分均可解释</li><li>独立学习实验：144 个训练源样本、48 个验证源样本、72 个测试源样本；不同集合由独立种子生成，词表与输入缩放范围预先固定。</li></ul><p>所有数值为教学构造，可通过导出数据核查；现场应用需独立真实数据验证。</p>"}, {"no": 4, "en": "NEXT STEP", "title": "从示范走向真实智能化", "html": "<p>已实现浏览器端 文本 MLP 训练与推理，卷积或全连接权重确实更新。意图分类不是文本生成，没有调用大语言模型；低分、陌生表达和混合意图需人工复核。 演示数据为教学合成，现场应用仍需独立真实资料、按井/样品分组验证与专业复核。</p><p>专业概念参考：<a href=\"https://www.slb.com/resource-library/oilfield-review/defining-series/defining-mud-logging\" target=\"_blank\" rel=\"noopener noreferrer\">SLB · Defining Mud Logging</a>。算法原理参考：<a href=\"https://www.tensorflow.org/tutorials/images/cnn\" target=\"_blank\" rel=\"noopener noreferrer\">TensorFlow CNN 教程</a>、<a href=\"https://scikit-learn.org/stable/modules/neural_networks_supervised.html\" target=\"_blank\" rel=\"noopener noreferrer\">MLP 与反向传播</a>、<a href=\"https://scikit-learn.org/stable/common_pitfalls.html\" target=\"_blank\" rel=\"noopener noreferrer\">防止数据泄漏</a>。本项目用原生 JavaScript 实现，并未加载这些库；合成数据与指标由本项目计算。</p>"}]}, "workflow": {"label": "案例流程", "title": "录井报告自动生成的可复现实验流程", "lead": ["让报告中的每一个结论，都能回到原始记录。", "每一步都说明输入、处理方法、可观察结果与常见陷阱。"], "stats": [["关键步骤", "4"], ["执行位置", "浏览器"], ["数据类型", "教学样本"]], "steps": [{"name": "接收原始记录", "role": "数据", "do": "输入教学记录并保留原文。", "effect": "让所有报告字段具有可核对来源。", "trap": "该简化解析器仅支持界面示例的字段格式。"}, {"name": "抽取与校验实体", "role": "特征", "do": "识别目标字段，检查深度顺序、全烃范围与荧光级别。", "effect": "缺失项显示待补充，异常值给出提示。", "trap": "规则漏识别时不能猜测补值。"}, {"name": "机器学习与深度学习对照", "role": "学习", "do": "保留原有专业基线；另用相同划分比较 k-NN 和 文本 MLP。固定 24 词表二值向量 → 20 单元 ReLU → 12 单元 ReLU → 三种复核意图。", "effect": "观察实际训练/验证损失、网络激活和参数变化。", "trap": "训练集更新权重，验证集选轮数；测试集不参与二者。"}, {"name": "冻结模型与独立验收", "role": "验收", "do": "恢复验证损失最低轮的权重，对 72 个测试样本推理；生成两种方法的混淆矩阵、准确率与宏平均 F1。", "effect": "浏览误判样本，导出数据、逐轮损失和模型权重。", "trap": "指标只对应合成任务；反复看测试集后再调参会削弱其独立验收意义。"}], "metrics": {"title": "看见训练过程，再判断结果", "html": "<figure style=\"margin:18px 0;padding:18px;border:1px solid #d7e6de;border-radius:10px;background:#f5f9f6\"><div style=\"overflow-x:auto\" tabindex=\"0\" aria-label=\"专业示意图，窄屏可横向查看\"><svg viewBox=\"0 0 800 250\" role=\"img\" aria-label=\"看清模型怎样学习\" style=\"display:block;width:100%;min-width:600px;font-family:system-ui,Microsoft YaHei,sans-serif\"><defs><marker id=\"arrow-看清模型怎样学习\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0 0L6 3 0 6\" fill=\"none\" stroke=\"#4a967c\"/></marker></defs><text x=\"20\" y=\"27\" font-size=\"16\" font-weight=\"600\" fill=\"#2d715a\">看清模型怎样学习</text><rect x=\"20\" y=\"62\" width=\"170\" height=\"64\" rx=\"8\" fill=\"#dfeee3\"/><text x=\"38\" y=\"88\" fill=\"#3b765a\" font-size=\"13\">训练 144 / 标签参与</text><text x=\"38\" y=\"110\" fill=\"#698c78\" font-size=\"11\">输入 → 前向计算 → 损失</text><path d=\"M202 94h54m-7-6 7 6-7 6\" fill=\"none\" stroke=\"#4d947a\" stroke-width=\"2\"/><rect x=\"265\" y=\"62\" width=\"255\" height=\"64\" rx=\"8\" fill=\"#e0e9f1\"/><text x=\"285\" y=\"87\" fill=\"#456d87\" font-size=\"13\">反向传播 · Adam 更新参数</text><text x=\"285\" y=\"109\" fill=\"#698393\" font-size=\"11\">每批 12 个样本 / 实时记录交叉熵</text><path d=\"M390 138v30H107v-30m-6 8 6-8 6 8\" fill=\"none\" stroke=\"#789c89\" stroke-width=\"2\"/><text x=\"145\" y=\"191\" fill=\"#6b8e77\" font-size=\"12\">重复训练，权重与损失真实变化</text><rect x=\"556\" y=\"62\" width=\"220\" height=\"64\" rx=\"8\" fill=\"#f1e9d8\"/><text x=\"574\" y=\"88\" fill=\"#99835c\" font-size=\"13\">验证 48 / 选择最低损失轮次</text><text x=\"574\" y=\"110\" fill=\"#99835c\" font-size=\"11\">不进入梯度，不更新权重</text><rect x=\"556\" y=\"160\" width=\"220\" height=\"64\" rx=\"8\" fill=\"#e1ece8\"/><text x=\"574\" y=\"186\" fill=\"#527a65\" font-size=\"13\">测试 72 / 冻结权重后验收</text><text x=\"574\" y=\"208\" fill=\"#789783\" font-size=\"11\">混淆矩阵 · 准确率 · 宏平均 F1</text><path d=\"M666 133v20m-6-8 6 8 6-8\" fill=\"none\" stroke=\"#789c89\" stroke-width=\"2\"/></svg></div><figcaption style=\"font-size:12px;color:#6a8275;margin-top:9px;line-height:1.8\"><b>文本 MLP：</b>固定 24 词表二值向量 → 20 单元 ReLU → 12 单元 ReLU → 三种复核意图。学习显示复核、工况排查和层界复核三种意图，与词向量 k-NN 对照。报告实体抽取和模板初稿仍保留原文依据。</figcaption></figure><p>字段完整度 = 已抽取字段 / 5。质量提示统计缺失字段、反向井段、超范围全烃和荧光值。余弦相似度只反映词向量接近程度；不存在模型准确率承诺。 神经网络实验与原专业基线使用不同教学数据，各自独立评估。新实验准确率为正确分类数/72，宏平均 F1 为各类 F1 的均值；只比较同一新实验中的 k-NN 和神经网络。</p><div class=\"p-diagram\" style=\"padding:16px;background:#f4f8f6;border:1px solid #dce7e1;border-radius:10px\"><svg viewBox=\"0 0 685 125\" role=\"img\" aria-label=\"录井报告自动生成概念流程\"><rect x=\"18\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e5f0e9\"/><text x=\"31\" y=\"51\" font-size=\"10\" fill=\"#81958d\">01</text><text x=\"90\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">现场记录</text><path d=\"M167 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"186\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#e8eff5\"/><text x=\"199\" y=\"51\" font-size=\"10\" fill=\"#81958d\">02</text><text x=\"258\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">实体抽取</text><path d=\"M335 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"354\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#eceaf5\"/><text x=\"367\" y=\"51\" font-size=\"10\" fill=\"#81958d\">03</text><text x=\"426\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">参考检索</text><path d=\"M503 65h14m-5-4 5 4-5 4\" stroke=\"#8da59a\" fill=\"none\"/><rect x=\"522\" y=\"30\" width=\"145\" height=\"70\" rx=\"9\" fill=\"#f4edde\"/><text x=\"535\" y=\"51\" font-size=\"10\" fill=\"#81958d\">04</text><text x=\"594\" y=\"78\" text-anchor=\"middle\" font-size=\"14\" fill=\"#38594f\">报告初稿</text></svg></div>"}, "fails": [{"name": "不规范表达", "why": "目前按示例格式解析，不支持所有自然语言变体。"}, {"name": "字段矛盾", "why": "有文本不等于有效数据，需要范围与逻辑检查。"}, {"name": "参考库覆盖不足", "why": "无相关词时不输出臆造建议，交给人工补充。"}]}, "demo": {"mode": "page", "html": "demo/index.html", "js": "demo/demo.js", "label": "交互演示", "intro": "让报告中的每一个结论，都能回到原始记录。", "height": 1100}}}, "path": "cases/mud-report-lab/demo/index.html", "zip": "案例包/录井-录井报告自动生成.zip"}];
